import{z as n,x as A,o as l,c as p,q as t,j as i,D as E,d as B,s,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"LSM 读放大与布隆","description":"","frontmatter":{"title":"LSM 读放大与布隆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-read-amplification.md","filePath":"cs/lsm-read-amplification.md","lastUpdated":1791413859000}'),d={name:"cs/lsm-read-amplification.md"};function m(c,a,D,F,f,S){const o=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="lsm-读放大与布隆" tabindex="-1">LSM 读放大与布隆 <a class="header-anchor" href="#lsm-读放大与布隆" aria-label="Permalink to &quot;LSM 读放大与布隆&quot;">​</a></h1><div class="epigraph"><p>点查可能打开每一层的文件；布隆过滤器以假阳性换「文件里肯定没有」的跳过，读放大才从层数里降下来。</p><footer>—— 据 Bloom, Space/Time Trade-offs in Hash Coding, CACM 1970；LevelDB/RocksDB；O&#39;Neil LSM</footer></div><p><a href="/cs/lsm-compaction">上一课</a>画出 memtable 与多层 SST。本课不选 compaction 形状。缺口是读路径：点查最坏触及每层多个文件（L0 重叠）。每文件一次 I/O 甚至一次索引块，放大远大于 B+ 的 \\(O(\\log n)\\) 页。布隆过滤器（及 fence 指针、区间）先否定「键不在此文件」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布隆：位图+多哈希，可能假阳性（空跑一次 I/O），无假阴性（说没有就真没有，对集合存在而言）。删除与墓碑：过滤器按文件构建时包含当时键；compaction 重建。缺口是<strong>把过滤器放进文件元数据</strong>，读路径先查内存里的布隆再决定是否读索引块。</p><p><span class="marginnote">数字实例：1% 假阳性率约每键花 10 位——百万键文件的布隆只要约 1.2 MB，常驻内存；而一次假阳性的代价是整整一次磁盘读加索引块。过滤器体积只有数据的千分之几，却能把大多数「肯定无」文件挡在 I/O 之外，这笔账几乎稳赚。</span></p><p>范围扫描：布隆帮不上「范围内是否有键」的全体否定（有区间过滤器、prefix bloom 变体）。范围仍要走有序文件的迭代器堆（多路归并各层）。</p><p><span class="marginnote">Bloom 1970。计算机课布隆过滤器已有；本课接到 SST。quotient/cuckoo filter 是替代，点名不展开。假阳性率与位数是空间换 I/O。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个 SST 一块布隆（或按数据块分）。点查：从新到旧层，memtable → L0 各文件 → 更高层至多一个文件（leveled 时）。全 miss 仍可能因假阳性读盘。缓存索引块与布隆本身，避免过滤器也 miss。</p><p>统计：优化器对 LSM 表的代价应计期望打开文件数，不是当成堆扫。否则 DP 会误判。</p><p><span class="marginnote">常见误区：初学者容易把布隆的「可能有」理解成「多半有」。假阳性率是一个固定概率，与键是否存在无关；过滤器只负责便宜地说「肯定没有」，所有「可能有」的回答都必须真读文件验证，不存在捷径。</span></p>',12)),(l(),i(r,null,{default:E(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E7%82%B9%E6%9F%A5%E9%94%AE%22%5D%20--%3E%20BF%5B%22%E6%96%87%E4%BB%B6%E5%B8%83%E9%9A%86%22%5D%0A%20%20BF%20--%3E%7C%22%E8%82%AF%E5%AE%9A%E6%97%A0%22%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%E6%96%87%E4%BB%B6%22%5D%0A%20%20BF%20--%3E%7C%22%E5%8F%AF%E8%83%BD%E6%9C%89%22%7C%20IDX%5B%22%E8%AF%BB%E7%B4%A2%E5%BC%95%E5%9D%97%20%2F%20%E6%95%B0%E6%8D%AE%E5%9D%97%22%5D%0A%20%20SKIP%20--%3E%20NXT%5B%22%E4%B8%8B%E4%B8%80%E6%96%87%E4%BB%B6%E6%88%96%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"写放大与读放大此消彼长：更积极 compaction 减少层与重叠，读变好、写变重。布隆降低读放大但不降层数本身。块缓存命中时「打开文件」可能只是内存比较。",-1)),a[5]||(a[5]=e("p",null,"与延迟物化：SST 内部可以是行或列；布隆在键上，不在投影列上。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"为什么重要：优化器若把 LSM 点查当成「一次索引查找」计价，join 顺序的 DP 就会系统性选错计划——LSM 的真实代价是「期望打开文件数」，要按 memtable 加 L0 重叠数加每层至多一个来估。")],-1)),(l(),i(r,null,{default:E(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%82%B9%E6%9F%A5%E9%94%AE%20k%22%5D%20--%3E%20MEM%5B%22%E6%9F%A5%20memtable%3A%20%E5%91%BD%E4%B8%AD%E5%8D%B3%E8%BF%94%E5%9B%9E%22%5D%0A%20%20MEM%20--%3E%20L0%5B%22L0%3A%20%E9%80%90%E4%B8%AA%E6%9F%A5%E9%87%8D%E5%8F%A0%E6%96%87%E4%BB%B6%2C%20%E5%8F%AF%E8%BE%BE%E5%A4%9A%E4%B8%AA%22%5D%0A%20%20L0%20--%3E%20HIGHER%5B%22L1%20%E4%BB%A5%E4%B8%8A%3A%20%E6%AF%8F%E5%B1%82%E8%87%B3%E5%A4%9A%201%20%E4%B8%AA%E6%96%87%E4%BB%B6%22%5D%0A%20%20HIGHER%20--%3E%20BF%7B%22%E8%AF%A5%E6%96%87%E4%BB%B6%E5%B8%83%E9%9A%86%E6%80%8E%E4%B9%88%E8%AF%B4%3F%22%7D%0A%20%20BF%20--%3E%7C%22%E5%8F%AF%E8%83%BD%E6%9C%89%2C%20%E5%AE%9E%E9%99%85%E5%8D%B4%E6%97%A0%22%7C%20FP%5B%22%E5%81%87%E9%98%B3%E6%80%A7%3A%20%E7%99%BD%E4%BB%98%E4%B8%80%E6%AC%A1%20I%2FO%22%5D%0A%20%20BF%20--%3E%7C%22%E8%82%AF%E5%AE%9A%E6%97%A0%22%7C%20NEXT%5B%22%E8%B7%B3%E5%88%B0%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A%20%20FP%20--%3E%20NEXT%0A%20%20NEXT%20--%3E%20NF%5B%22%E5%85%A8%E9%83%A8%E6%9C%AA%E4%B8%AD%3A%20%E8%BF%94%E5%9B%9E%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较 leveled 与 tiered 的公式——下一课。也不把布隆当唯一跳过手段：zone map 在列存分析文件上做范围跳过，后课。</p><p>后课默认：LSM 点查先过滤器后数据；范围走多路迭代器。leveled 对 tiered：层内重叠政策不同，放大曲线不同。</p><p>假阳性是读放大的残余项，调位数直到 I/O 预算够。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>读放大来自多层与 L0 重叠；布隆跳过无键文件。</li><li>范围扫描主要靠有序归并，不是布隆。</li><li>leveled 对 tiered 下一课：compaction 形状决定放大。</li><li>出处：Bloom 1970；O&#39;Neil LSM；LevelDB/RocksDB。</li></ul>',6))])}const h=n(d,[["render",m]]);export{T as __pageData,h as default};
